function show(v: any): string {
  return typeof v === "bigint"
    ? String(v) + "n"
    : typeof v === "string"
      ? JSON.stringify(v)
      : typeof v === "symbol"
        ? "symbol"
        : Object.is(v, -0)
          ? "-0"
          : String(v);
}
function t(op: (a: any, b: any) => any, a: any, b: any): string {
  try {
    return show(op(a, b));
  } catch (e: any) {
    return e.name + ": " + e.message;
  }
}
function u(op: (a: any) => any, a: any): string {
  try {
    return show(op(a));
  } catch (e: any) {
    return e.name + ": " + e.message;
  }
}
function add(a: any, b: any): any {
  return a + b;
}
function sub(a: any, b: any): any {
  return a - b;
}
function mul(a: any, b: any): any {
  return a * b;
}
function div(a: any, b: any): any {
  return a / b;
}
function mod(a: any, b: any): any {
  return a % b;
}
function pow(a: any, b: any): any {
  return a ** b;
}
function and(a: any, b: any): any {
  return a & b;
}
function or(a: any, b: any): any {
  return a | b;
}
function xor(a: any, b: any): any {
  return a ^ b;
}
function shl(a: any, b: any): any {
  return a << b;
}
function shr(a: any, b: any): any {
  return a >> b;
}
function ushr(a: any, b: any): any {
  return a >>> b;
}
function same(a: any, b: any): boolean {
  return a === b;
}
function other(a: any, b: any): boolean {
  return a !== b;
}
function sameUnion(a: string | number | null, b: string | number | undefined): boolean {
  return a === b;
}
function truth(a: any): string {
  return a ? "yes" : "no";
}
function not(a: any): boolean {
  return !a;
}
function truthUnion(a: string | number | boolean | null | undefined): number {
  return a ? 1 : 0;
}
function text(a: any): string {
  return `<${a}>`;
}
function textOfNumber(a: number): string {
  return `${a}`;
}
function textOfInteger(a: number): string {
  return `${a | 0}:${(a | 0) + 1}`;
}
function textOfUnion(a: string | number | boolean | null | undefined): string {
  return "" + a;
}
function addToText(a: string, b: any): string {
  return a + b;
}
function addNumberOrText(a: number | string | null, b: number | string | undefined): number | string {
  return (a as any) + (b as any);
}
function one(s: any): string {
  if (s === "abc") return "is abc";
  return "no";
}
function ladder(s: any): string {
  if (s === "a") return "a";
  else if (s === "7") return "seven";
  else if (s === "abc") return "abc";
  else if (s === "abd") return "abd";
  else if (s === "Ā") return "A-macron";
  else if (s === "told") return "told";
  else if (s === "a text of thirty-two characters!") return "32";
  else if (s === "") return "empty";
  return "none";
}
function ladderOfString(s: string): number {
  switch (s) {
    case "a":
      return 1;
    case "7":
      return 2;
    case "abc":
      return 3;
    case "abd":
      return 4;
    case " 12 ":
      return 5;
    case "0x10":
      return 6;
    case "Ā":
      return 7;
    case "Āb":
      return 8;
    default:
      return 0;
  }
}
function ladderOrNil(s: string | null | undefined): number {
  if (s === "abc") return 1;
  if (s === "7") return 2;
  if (s === "ab") return 3;
  return 0;
}

